import multiprocessing
import pickle

import pytest

from tenacity import Future, RetryError, retry, retry_if_result, stop_after_attempt


@retry(stop=stop_after_attempt(2))
def fail_in_worker(value):
    raise ValueError(value)


@retry(stop=stop_after_attempt(2), retry=retry_if_result(lambda result: True))
def return_in_worker(value):
    return value


@pytest.mark.parametrize('protocol', range(pickle.HIGHEST_PROTOCOL + 1))
@pytest.mark.parametrize('failed', [False, True])
def test_retry_error_pickle(protocol, failed):
    value = ValueError('failed') if failed else {'result': 42}
    expected = RetryError(Future.construct(2, value, failed))
    actual = pickle.loads(pickle.dumps(expected, protocol=protocol))
    assert actual.last_attempt.attempt_number == 2
    assert actual.last_attempt.failed == failed
    if failed:
        with pytest.raises(ValueError, match='failed'):
            actual.reraise()
    else:
        assert actual.last_attempt.result() == value


@pytest.mark.parametrize('start_method', multiprocessing.get_all_start_methods())
@pytest.mark.parametrize('worker', [fail_in_worker, return_in_worker])
def test_retry_error_multiprocessing(start_method, worker):
    with multiprocessing.get_context(start_method).Pool(1) as pool:
        with pytest.raises(RetryError) as raised:
            pool.map_async(worker, [42]).get(timeout=20)
    attempt = raised.value.last_attempt
    assert attempt.attempt_number == 2
    if worker is fail_in_worker:
        assert isinstance(attempt.exception(), ValueError)
        assert attempt.exception().args == (42,)
    else:
        assert attempt.result() == 42
